INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1531507-math399', 'stk-omar4', 'MATH 399', 'info', '{"desc": "Math 399 - Summer Training\nTerm 203\n\nالتدريب الصيفي هو متطلب للتخرج ولا يكون آخر ما ينهيه الطالب , لابد على الأقل من فصل دراسي بعده (ربما تغير الوضع أو هناك استثناءات) وفي العادة ينتهي منه الطالب في الصيف الذي يسبق سنته الأخيرة.\nتتعدد فرص الحصول على التدريب الصيفي بناءً على طلب السوق والشركات ومعاهد البحوث وعلى أداء الطالب وسيرته الذاتية.\nأكثر طلاب الرياضيات تتمحور فرصهم التدريبية حول ( التدريب في القسم في الجامعة - التدريب في أرامكو - التدريب في كاوست ) وقد يحصلون على فرصة في معاهد أبحاث أخرى مثل كاكست او شركات تتطلب عمل إحصائي أو حتى مالي واكتواري.\n\nكانت تجربتي في التدريب الصيفي داخل أسوار الجامعة تحت إشراف قسم الرياضيات والإحصاء , لمدة ما يقارب الشهرين.\nالخطة الأساسية هي عمل بحث او تقرير مبسط او مشروع كمدخل بحثي ويتم التركيز فيه على البحث وطرقه أكثر من المحتوى ( في الغالب المحتوى ليس جديد كليًا على الطالب , لكن قد يكون البحث جديد تمامًا ).\n\nكانت هذه هي المواضيع المقدّمة من قبل القسم ( مع متطلباتها بين الأقواس ) :\n\nSylow’s Theorems (Math323 with B+ at least)\nSmart Graphs (Math425)\nMultigrid Methods for 2D Stokes Equations (Math371)\nComputational Mathematics (Capable of running numerical simulations)\nLocal Curvature of Functions With Many Variables via Hessian Matrix (Math201,Math225 with B+ at least)\nAdditively Idempotent Semirings and Their Applications (Math323)\nThe Heat Equation : Modeling and Solving (Math371)\nMath202 Textbook Projects (Background on programming C++, Mathematica, or similar)\n\nونلاحظ تنوع المواضيع من ناحية الرياضيات البحتة والتطبيقية.\nكان بحثي متعلق ب Sylow’s Theorems وبصفته بحث نظري لم يكن يتطلب التعامل مع أي برنامج أو تطبيق محاكاة أو غيره.\nكانت الخطة مقسمة إلى عدة أسابيع ( قد تختلف من مشرف إلى مشرف ) , وكانت عن طريق تقسيم البحث إلى جزئيات أصغر ثم البحث في جزئية لمدة اسبوع وفي نهاية الأسبوع يتم تسليم النسخة (Draft) للدكتور المشرف ويتم تصحيحها وتنقيحها وهكذا حتى انتهاء المدة واعتماد البحث النهائي. في ختام البرنامج يطلب من الطالب تقديم عرض عن موضوعه (وحضر العرض اثنان من أعضاء هيئة التدريس بالإضافة إلى مشرفي) وشرح بسيط لأهم النتائج والتطبيقات.\n\nنصائح مهمة للبحث :\n1- احرص على سؤال المشرف عن الأشياء المهمة وحاول التعلم أكثر بنفسك.\n2- اجعل تركيزك بالمقام الأول على البحث وطرقه , كتابة البحث بطريقة أكاديمية , استخدام لغة مناسبة , تنسيق مناسب.\n3- تعلم المهارات المطلوبة, مثلا Matlab, Mathematica لو احتجتها , او LaTeX لكتابة التقرير بتنسيق ممتاز.\n4- ابحث عن مراجع مناسبة وممتازة واعرضها على مشرفك.\n5- نقطة مهمة جدًا وهذي ذكرها مشرفي ( أهم شي الصدق والعمق ) الصدق يعني الاخلاص في كتابة التقرير كتابة شخصية بذاتك دون النسخ او النقل الغير مشروع , والعمق يعني فهم محتوى البحث وكل حرف كُتب فيه.\n\nنصائح مهمة للعرض :\n1- لا تجعله يتجاوز 20 شريحة بشكل عام , وفي كل شريحة لا تزد على 3 نقاط.\n2- لا تضع اي اثباتات او عبارات طويلة , فقط رؤوس أقلام وأهم التعاريف والمبرهنات والنتائج والتطبيقات.\n3- التحضير الجيد مفيد جدًا, لطلاقة اللسان أثناء العرض وللالتزام بالوقت (كان الوقت المطلوب مني قرابة 35 دقيقة و10 دقائق أسئلة ونقاش).\n4- لا تتحمس جدًا ف تستعجل أكثر من اللازم , كن هادئًا واطرح عرضك بثقة وهدوء.\n5- يفضل استخدام Beamer للعرض بطريقة اكثر احترافية.\n6- استقبل الأسئلة والنقاشات بصدر رحب , لا تجب على الاسئلة بشيء لا تعلم صحته , أن تقول (لا أعلم) او (أحتاج للبحث عنها) أفضل بكثير من أن تعطي معلومات خاطئة.\n\nختامًا أود التنويه إلى أن التدريب الصيفي لطالب الرياضيات يدخل في المعدل وعليه ساعتان (with 2 credit hours) وعليه Grade أيضًا.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-399-summer-training/184162/1", "user": "OMAR4", "ts": 1629998249000, "tid": 184162, "pn": 1}}', 1629998249000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
